drop policy if exists follows_read on public.follows; create policy follows_read_connected on public.follows for select to authenticated using (follower_id = auth.uid() or following_id = auth.uid()); drop policy if exists notification_events_authenticated_read on public.notification_events; create policy notification_events_authenticated_read on public.notification_events for select to authenticated using (actor_user_id = auth.uid() or audience_scope in ('public','community'));
